mapper.update:
update ETR_SEC_STOCK
set PLEDGE_STOCK_NAME = #{pledgeStockName,jdbcType=VARCHAR},
    UPDATE_USER = #{updateUser,jdbcType=VARCHAR},
    UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP}
where PLEDGE_STOCK_ID = #{pledgeStockId,jdbcType=VARCHAR}

update ETR_SEC_STOCK
set IS_DEF_STOCK = #{isDefStock,jdbcType=VARCHAR},
    UPDATE_USER = #{updateUser,jdbcType=VARCHAR},
    UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP}
where CREATE_USER = #{createUser,jdbcType=VARCHAR}

    AND PLEDGE_STOCK_ID = #{defaultStock,jdbcType=VARCHAR}
